WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (525::BIGINT, 'Ella suele ayudar demasiado si ve su esfuerzo, volvería a llevar la clase con ella.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'a93f20343ff930d756662d96ba738ac31de9c8511a7e5ffbeaf0c3f4f46df968'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Explica muy completo, es un poco sarcástica pero las clases son bonitas, hace muchos quices, los primeros son horribles, pero es para que a usted le vaya mejor en el examen, a final de semestre se relaja más, deja tareas Morales para puntos extra o si le falta para pasar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '10161ab20a685b3a99da5335e13757dea2c329e7570579f75013f38514f4405a'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'Excelente profesora, domina la materia, se toma su tiempo en explicarla y ademas que para los trabajos y tareas esta abierta a neogicar fechas. Muy empatica. Recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1de45e140e495809a84f8edcb85eed73dbdb03485167edf9a18b6d48e17ea8b6'::TEXT, ARRAY[935]::BIGINT[]),
    (525::BIGINT, 'Planea muy bien la clase, explica claro, es muy amable y le interesa el rendimiento de sus estudiantes, deja trabajos morales que al final podría funcionar si le hace falta puntos. Evalúa lo que explica y revisa un poco duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-27T00:00:00+00:00'::TIMESTAMPTZ, '4da29b4a15e940ab76755627602ec6108f230eab5f4576bc823fe06177f07dae'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Regular. Las presentaciones no las comparte y son muy confusas, muchas fórmulas despilfarradas, y mientras usted las está copiando (que le va a costar, porque ni siquiera le hace zoom a la presentación) ella ya explicó el tema y pasa al siguiente. Quices difíciles.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-05-03T00:00:00+00:00'::TIMESTAMPTZ, '4a3a87cb09bfa88fe71dfb880c0a447675572c4dd0b2a81e87e673758372584c'::TEXT, ARRAY[1057]::BIGINT[]),
    (525::BIGINT, 'Es una pésima profesora, no tiene vocación, explica mal, es arrogante y sarcástica cuando se le pregunta algo, además da rúbricas mediocres que parecen de adorno porque califica a su antojo. En sí se pasa fácil porque no hace exámenes, pero es una vergüenza de profesora y persona.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e9fd661795001a6eb156eb6c9110cb85685e0972ff9f9d44f738e6bc02dba209'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'Muy sencillo pasar ya que no realiza exámenes, pero los trabajos son largos, además de que califica como se le antoja y castiga súmamente injusto algunos errores. Explica bien, pero es muy desordenada respecto a las notas de clase y fechas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd7641ecd9314cff4e5293cf1aed796d318daadbb470bcad08fbc39a67100a21f'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'Desordenada, mal humorada, mala explicando y califica como se le antoja. Se pasa bien pero no sin antes llevarse un colerón diario y matandose todos los días para salir con todo lo que deja y estarlo corrigiendo porque pasa cambiando lo que quiere. Es mejor 3 parciales presenciales con otro profe.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'b918a7c3df6b7d7e7f6da44713325027cfa5ff7a3db3b2243a59abf256320adc'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'La profe es buena nota, deja muchos trabajo en verano y califica bastante duro, todo tiene que ser a gusto de ella y no escucha mucho al estudiante, también es un poco arrogante y es dificil de corregir cuando realiza algo malo, lo cual hace que el curso sea dificil de pasar'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '37ae49c4d3043c82a9f85a58303223f7bbb2c21c2772698007c9ae250e66bad3'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'No la recomiendo para Cálculo Superior, es la segunda vez que lo llevé y me da la sensación por no decir que estoy segur@ de que no sabe de lo que habla, se enreda mucho, no está preparada para dar este curso y lo peor es que su actitud terca no deja que la intentes corregir por el bien de todos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-01-18T00:00:00+00:00'::TIMESTAMPTZ, '3670b523ff24fb4b1348ca7fa60259445716cd7f4e85e573b4e5bd1a369e37c0'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'La profesora tiene una forma efectiva de explicar, pero los exámenes y quizes son bastante difíciles, y al representar la mayor parte de la calificación (en verano 90 %), es difícil pasar.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a1822134953dfaad30494a0c675ef9a00b14e06b3a45f81155901b3fdcc7ed80'::TEXT, ARRAY[923]::BIGINT[]),
    (525::BIGINT, 'La profe es algo tuanis, esta dispuesta a aclarar dudas de los ejercicios, lo prepara bien para los exámenes con ejercicios difíciles en clase. Y suave a la hora de calificar exámenes. Deja muchas tareas(fáciles), NO GRABA LAS SESIONES.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2023-11-11T00:00:00+00:00'::TIMESTAMPTZ, '61611e498c6553ae4aca23b6c154f50c35b731d02c577d4764ade4c25699bdd2'::TEXT, ARRAY[1057]::BIGINT[]),
    (525::BIGINT, 'Explica excelente, hace que la materia quede clara, si entiende los ejercicios de la clase, le va a ir bien en los exámenes. No me gustó como califica las tareas, pero solo eso negativo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9b308f706b8bdb281742b55b745c2deacdb9e5d99fed14dce00ae2af865d8796'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '471e7cafbbed6894d53e7712fa16f4ff7c7870a2c30bfe3d9f53c580deeb503c'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Explica claro y atiende dudas sin problemas. En la clase presenta ejemplos de un nivel superior a los del examen, por lo que si entiende esos, le va a ir bien. Único inconveniente son quizzes duros pero se esfuerza en rescatar puntos por procedimiento. Súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0e53071e3d650c58571e90633ca3029994450f5747033c1f8d75b89226c752d1'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Excelente profesora, es como tener una amiga enseñándole super recomendada. Vayan a las clases porque ahí se aprende demasiado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cfc8cc761a2d852ccb47826f8ab58b9cb410cf4e61f5c60fbbb24ee1881aeaba'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Recomiendo demasiado llevar CDI con Verónica, explica ejercicios difíciles en clase, lo que hace que uno llegue al examen preparado. Además hace muchos ejercicios, es atenta y anuente a responder dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'dbbae5fe5f5545bd1bd79d8136eaab233e1664d04e746eee33d0ea12192b8d08'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Si quiere pasar CDI, llevelo con ella. Los ejercicios que hace en clase son de alto nivel y cuando llega la examen, se le hace super facil. Eso sí, haga todo lo que ella le pide y ademas, vaya al día con la practica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '109efaa1b1bfe37dbde8110d380118ea5c498faa646e90c667e59e218f78099e'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Es una buena profe. Solo que hay que tener cuidado de como quiere los procedimientos, porque si no baja muchos puntos, esto fue en Verano. Pero en todo lo demás explica muy bien y siempre atiende dudas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '8b9b5326dedecbc0541a05a83f9758c9f6938ca8b3e6115e1e81bc611956f23e'::TEXT, ARRAY[1018]::BIGINT[]),
    (525::BIGINT, 'Lo llevé en verano, 3 dias de quices y el 4 dia era de examen, enseña muy bien y lo prepara a uno super bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'e5ba296512c709a5350664daae5ef501cd83e8f90add1966eb7c44d44fc706a5'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Explica más o menos bien. Pero es demasiado irrespetuosa con los estudiantes. Si le escribe por Telegram, prepárese para que lo trate mal y que haga lo posible por no ayudarle en nada. Los materiales de la cátedra son buenos, por lo que igual pasa aunque no asista a clases.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0929a23b75ba61e2808651ef89208c3b311ea97ef8463b9e3909ea5ec58ed3b9'::TEXT, ARRAY[1057]::BIGINT[]),
    (525::BIGINT, 'La profe es muy buena dando clases, pero como persona a veces se molesta y no diferencia lo personal con lo profesional'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '76cced0999d5841cdbf7e8fded6e22e33d0a46af9fcc8a26daffce55a1097ac6'::TEXT, ARRAY[1057]::BIGINT[]),
    (525::BIGINT, 'Por alguna razon se puso castrosa cuando estabamos presentando el proyecto, y los califica duro. En virtual pues es sencillo porque es pura catedra, pero presencial no quiero imaginarlo. La verdad explica bien, y no se hasta que nivel es culpa de la catedra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, '02ad172166da297f8a2185376128c7aaab79fd8c5c3de363838e8fa72d4e99ec'::TEXT, ARRAY[1057]::BIGINT[]),
    (525::BIGINT, 'Excelente profesora, las clases se dedica a explicar la materia y luego a hacer muchos ejercicios con el fin de que el estudiante practique. Muchos quices y tareas pero no son pesados y lo ayudan a uno con los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd4cd5aad29d2b91b53f52ea2b832cf18afae63f4c357322d424324d8743f3028'::TEXT, ARRAY[634]::BIGINT[]),
    (525::BIGINT, 'Deja muchas tareas pero que ayudan mucho es una excelente persona y mejor profesora siempre dispuesta ayudar al estudiante pregunte sin miedo ella siempre ayuda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '0f9bb24617e8ff441d09e9a1f13e2aede9f50464a3454a77f1fed8c39ca06c9d'::TEXT, ARRAY[634]::BIGINT[]),
    (525::BIGINT, 'Es una profesora que vela por la compresnion del estudiante y se preocupa por el, explica de manera muy clara y no le importa repetir las veces que sea necesaria, deja muchas tareas pero ella misma te puede ayudar si no la entiendes, definitivamente es una gran opcion matricular con ella.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-27T00:00:00+00:00'::TIMESTAMPTZ, '5b1c7bb8c6deff801145d83a8ed987f0fd29a179e91cea5344d13d2c280f4553'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-08-29T00:00:00+00:00'::TIMESTAMPTZ, '0908a5e58713fb3b6ff2c65c7902e4885b43f16932ea34f9e02ee99410ff0a1d'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'La profe es muy buena, explica de más por lo que tiene que tener cuidado por que puede resultar más complicado, aún así si usted el entiende va a hacer los quices y parciales de la GAAP súper sobrado. Deja tareas semanales pero si usted le habla le da más tiempo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '920fe5bfe9f2f2d217686cf889369eff1e7fbe9209f239906b8768db33384e02'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Muy buena profe, hacia bastantes ejemplos que servían para mejorar el nivel de la materia. No se molestaba en explicar otra vez, e incluso podías pedirle un ejercicio de una tarea o quiz pasados. Pasé gracias a ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '69410430750ec723096a10bcb96b5caca56020e24feab1b993ce4ab7c2b062e3'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Ayuda mucho al estudiante. El curso fue virtual, entonces dejó tareas semanales para que los quices de cátedra no tuvieran tanto valor, eso sirve mucho. Premia a la gente que va a todas las clases.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'd1006bf8d50fac22e0f9a8470a885b85b8220f460d03959aa450bee9885b2092'::TEXT, ARRAY[634]::BIGINT[]),
    (525::BIGINT, 'La profe es buena, solo que tiene que estar concentrado al 100 con lo que está haciendo, ya que va bastante rápido. Consejo: si escribe lento, lo mejor es que se busque otro profe, o va a terminar con un montón de fotos de la pizarra, se lo digo por experiencia xd. Con la virtualidad no cambió nada'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '9d1ade8fd007ea7bcf4c07751b66c4d6b3cf2e6575da50f6581eda988e65fecb'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'f181bec34a659099d8e8f1b2c570737b18f376d87b2217e5bda3861bd5a623f9'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '7de0435be0c79582e476e87114f751c93de04196250edb037c5f4a61e5a8e9d2'::TEXT, ARRAY[923, 605, 2444]::BIGINT[]),
    (525::BIGINT, 'La profe se preocupa por que el grupo entienda, no se sienta mal si no entiende en clases, en horas consulta o a final de clases ella atiende, el único defecto es que si no entiende con varios ejercicios se puede llegar a molestar, estudie para los quices y ella si lo cuida en el examen da pistas :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'c639d90815c651cdc002a072dee5c359a1bd500916aa85a6b0f27a6f278d179d'::TEXT, ARRAY[605, 563]::BIGINT[]),
    (525::BIGINT, 'Excelente profesora, realmente le importa que el estudiante aprenda, se toma el tiempo para atender dudas, deja muchas tareas (morales) para que el estudiante practique, nunca se atrasa con la materia, super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3c8c6f68aba27d004ae5efd8577ee18cca3122f985611a994fbefabc9bf26d61'::TEXT, ARRAY[1018, 563, 605]::BIGINT[]),
    (525::BIGINT, 'Simplemente es la mejor profe que hay en el TEC de Limón, tiene muchos métodos para resolver problemas de la manera más facil. Es un amor. Ayuda mucho a los estudiantes, pero tiene que mostrarle interés en el curso. Y tiene una método de las (tareas morales) que pueden ayudar para pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2018-11-19T00:00:00+00:00'::TIMESTAMPTZ, '9d2d3d82d50ba67225c42d84d31b4df3367c7a8f9ea603fa3a164b6f24efcfcc'::TEXT, ARRAY[563]::BIGINT[]),
    (525::BIGINT, 'Excelente profe, sólo es de ponerle porque si es ruda, enseña y prepara para lo más difícil pero bien que mal te sirve como estudiante. Si eres diciplinado lo pasas con buenas notas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '2282f754359a38e3f107a4464737bb82627c072422fb5ec9c440f86f2a86bfc6'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Hace quices moderados, le ayuda a dar pistas en los examenes. Pero, tiene su defecto de alterarse en cuando ella explica un tema más de 3 veces y los estudiantes no le entienden. Si llevas el curso de matemática discreta, preparate para muchas tareas que deja.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd4dcb1a3e3e185c3e20f1e38115d43702214b09253c3c0853ec7b2a405d539c4'::TEXT, ARRAY[1018]::BIGINT[]),
    (525::BIGINT, 'Muy excelente profesora , es un amor , súper recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2501ba5937f05b3ce1d67f3bc8effbc9fd1fb16ac5320e3c66fe25a1b535c1a8'::TEXT, ARRAY[634]::BIGINT[]),
    (525::BIGINT, 'No tiene claridad en cuanto rubros de evaluación, las tareas son excesivas y los quices que realiza son extremadamente largos y difíciles, deja laboratorios sin explicar las herramientas, cero recomendada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2017-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'f11ba3a8f4402706ecfbb96b6c42756c4fd027bd91409615204372a8db34ddc5'::TEXT, ARRAY[103]::BIGINT[]),
    (525::BIGINT, 'Es una profesora excelente, simplifica bastante los temas difíciles y explica lo que de verdad importa, no pierde el tiempo en las clases, hace muchos ejemplos y califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'dc89495adf6af92f1bb73c8320bf67b4907337cdc3aeb78939a26b75b696597f'::TEXT, ARRAY[605]::BIGINT[]),
    (525::BIGINT, 'Una vez se me cerró el gapp sin querer, literalmente era un quiz de una hora y al min 32 se me cerró por conexión a Internet le pedí que me lo habilitará de nuevo ya que me quedaba aún tiempo y como sólo salía un intento no podía de nuevo, no quiso habilitarmelo nuevamente... Un ejemplo de como es.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-01-03T00:00:00+00:00'::TIMESTAMPTZ, '8365992ae448066c164dbd2dafae0e5ea558a499ad9e94e1b16f87630fe27bab'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
